buggy.period_from_min_timestamp_us_direct_fiel:
import pandas as pd
from pandas import Timestamp, Period

def run():
    ts = Timestamp(Timestamp.min.value, unit='us')
    try:
        per = Period(ts, freq='us')
        return {
            'per_repr': repr(per),
            'year': int(per.year),
            'month': int(per.month),
            'day': int(per.day),
            'hour': int(per.hour),
            'minute': int(per.minute),
            'second': int(per.second),
        }
    except Exception as e:
        return {'per_repr': None, 'error_type': type(e).__name__}

out = run()
probe('per_repr', out.get('per_repr'))
for k in ['year','month','day','hour','minute','second']:
    if k in out:
        probe(k, out[k])
if 'error_type' in out:
    probe('error_type', out['error_type'])

